import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2022_energy.csv')
adj_df = pd.read_csv(ADJACENCY_PATH)

# Prepare adjacency dictionary
adj_dict = {}
for borough in df['borough'].unique():
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adj_dict[borough] = neighbors

# Initial values
values = df.set_index('borough')['Energy_value'].to_dict()
boroughs = list(values.keys())

# ITERATIVE-R method implementation
def iterative_r_outlier_detection(values, adj_dict, max_iter=10, threshold=2.5):
    residuals = {}
    standardized_residuals = {}

    for _ in range(max_iter):
        # Calculate neighborhood averages
        neighborhood_avgs = {}
        for borough in boroughs:
            neighbors = adj_dict.get(borough, [])
            neighbor_values = [values[n] for n in neighbors if n in values]
            neighborhood_avgs[borough] = np.mean(neighbor_values) if neighbor_values else np.nan

        # Calculate citywide relationship (regression of value vs neighborhood avg)
        valid_data = [(values[b], neighborhood_avgs[b]) for b in boroughs 
                     if not np.isnan(neighborhood_avgs[b])]
        y, x = zip(*valid_data)
        x = np.array(x)
        y = np.array(y)
        if len(x) > 1:
            slope, intercept = np.polyfit(x, y, 1)
        else:
            slope, intercept = 1, 0

        # Calculate residuals
        for borough in boroughs:
            if borough in neighborhood_avgs and not np.isnan(neighborhood_avgs[borough]):
                predicted = slope * neighborhood_avgs[borough] + intercept
                residuals[borough] = values[borough] - predicted
            else:
                residuals[borough] = np.nan

        # Standardize residuals
        valid_residuals = [r for r in residuals.values() if not np.isnan(r)]
        if len(valid_residuals) > 1:
            mean_res = np.mean(valid_residuals)
            std_res = np.std(valid_residuals)
            for borough in boroughs:
                if not np.isnan(residuals[borough]):
                    standardized_residuals[borough] = (residuals[borough] - mean_res) / std_res
                else:
                    standardized_residuals[borough] = np.nan

        # Check convergence (no boroughs beyond threshold)
        extreme_found = False
        for borough in boroughs:
            if borough in standardized_residuals and not np.isnan(standardized_residuals[borough]):
                if abs(standardized_residuals[borough]) > threshold:
                    extreme_found = True
                    # Temporarily remove the most extreme value
                    if standardized_residuals[borough] == max(standardized_residuals.values()):
                        del values[borough]
                    elif standardized_residuals[borough] == min(standardized_residuals.values()):
                        del values[borough]
                    break
        if not extreme_found:
            break

    return standardized_residuals

# Run detection
standardized_residuals = iterative_r_outlier_detection(values.copy(), adj_dict)

# Get City of London's result
city_of_london_z = standardized_residuals.get('City of London', np.nan)

# Determine final answer
if not np.isnan(city_of_london_z):
    if city_of_london_z > 2.5:
        result = f"FINAL ANSWER: OUTLIER - HIGH (z = {city_of_london_z})"
    elif city_of_london_z < -2.5:
        result = f"FINAL ANSWER: OUTLIER - LOW (z = {city_of_london_z})"
    else:
        result = f"FINAL ANSWER: NOT AN OUTLIER (z = {city_of_london_z})"
else:
    result = "FINAL ANSWER: NOT AN OUTLIER (z = nan)"

print(result)
